// Live operations contain only live resources.
interface OperationsContext {
  database: Database;
  images: ObjectStore;
  quarantine: ObjectStore;
}
// LegacyRestoreContext stays in an offline tool.

// One live codec path.
const result = await processComparisonTask({
  task, images: env.IMAGES, codecs: await codecsReady,
});

type OperationsMessage =
  | { kind: 'status'; runId: string }
  | { kind: 'maintenance'; step: 'promotion' | 'history' | 'retention' }
  | { kind: 'continue' }; // temporary old-message decoder

// Proposed: baseline owns immutable original bytes through a run pin.
await atomic(db, [
  pinRun(sourceRunId, `baseline:${snapshotId}`),
  setBaseline({ snapshotId, sourceRunId, comparisonId }),
]);

type ClosedRunSummary = {
  id: string; testedSha: string; status: string;
  decisions: readonly DecisionReceipt[];
  evidenceExpiresAt: number | null;
};
